"""Check runner-schema compatibility and rejection gates without launching Java.

Inputs are explicitly synthetic: old raw records are copied into temporary files
and their arm/configuration labels changed. They are never performance evidence.
"""
import argparse
from copy import deepcopy
import importlib.util
import json
from pathlib import Path
import tempfile

import runtime_identity as identity

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('publication_driver', HERE / 'run-comparison.py')
driver = importlib.util.module_from_spec(spec)
spec.loader.exec_module(driver)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    old = driver.ROOT / 'result-coordinate-evidence/compact-page-followup/comparison-v1'
    protocol = {'selection': {'fixtureMasks': {'fanout': ['measurement'], 'shared-tail': ['l0', 'l1']}}}
    runtime = {'descriptor': {'sourceIdentity': 'synthetic-validator-input-not-measurement'}}
    positives, negatives, evidence = [], [], []
    paired = {}
    with tempfile.TemporaryDirectory(prefix='publication-validator-synthetic-') as temp:
        root = Path(temp)
        for fixture in driver.FIXTURE_ORDER:
            for arm in driver.ARMS:
                old_arm = 'current-off' if arm == 'off' else 'current-dense'
                old_folder = next(old.glob('round-00-*-'+fixture+'-*-'+old_arm))
                source_file = old_folder / 'samples.jsonl'
                audit_file = old_folder / 'root-host-audit.json'
                evidence.append({'path': str(source_file), 'sha256': identity.sha(source_file)})
                records = [json.loads(line) for line in source_file.read_text().splitlines()]
                metadata = records[0]
                metadata['arm'] = arm
                metadata['source'] = runtime['descriptor']['sourceIdentity']
                metadata['perQueryLedgerLimitBytes'] = 536870912
                props = driver.arm_properties(protocol, fixture, arm)
                metadata['jvmArguments'] = driver.JVM + ['-D'+k+'='+v for k,v in props.items()]
                metadata['systemProperties'] = {'rdf4j.lmdb.hotCounters': 'true',
                    driver.BUDGET_PROPERTY: '536870912', **props}
                for sample in records[1:]:
                    sample['arm'] = arm
                folder = root / (fixture+'-'+arm)
                folder.mkdir()
                (folder / 'samples.jsonl').write_text('\n'.join(json.dumps(r) for r in records)+'\n')
                (folder / 'root-host-audit.json').write_bytes(audit_file.read_bytes())
                _, samples, _, _, validation = driver.validate_run(folder, fixture, arm, runtime, protocol)
                assert validation['resultValidity'] == 'passed' and validation['targetQualified']
                positives.append({'fixture': fixture, 'arm': arm, 'queryCount': len(samples)})
                if arm != 'off':
                    paired[fixture, arm] = {'fixture': fixture, 'round': 0, 'samples': samples}
        for fixture in driver.FIXTURE_ORDER:
            all_run = paired[fixture, 'dense-all']
            omit_run = paired[fixture, 'dense-omit']
            assert driver.dense_pair_audit(all_run, omit_run)['passed']
            altered = deepcopy(omit_run)
            altered['samples'][0]['counters']['lazyValueCalls'] += 1
            assert not driver.dense_pair_audit(all_run, altered)['passed']
            negatives.append({'fixture': fixture, 'rejects': 'one resolver call changed in first warmup'})
        folder = root / 'fanout-dense-all'
        records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
        records[-1]['ledgerAfterBytes'] = 1
        (folder / 'samples.jsonl').write_text('\n'.join(json.dumps(r) for r in records)+'\n')
        try:
            driver.validate_run(folder, 'fanout', 'dense-all', runtime, protocol)
        except ValueError as exc:
            assert 'unreleased ledger' in str(exc)
            negatives.append({'fixture': 'fanout', 'rejects': 'one retained ledger byte'})
        else:
            raise AssertionError('Ledger leak accepted')
    identity.write_new(args.output, {'syntheticValidatorInputsOnly': True, 'benchmarkJvmsLaunched': 0,
        'driverSha256': identity.sha(HERE / 'run-comparison.py'),
        'helperSha256': identity.sha(HERE / 'runtime_identity.py'),
        'selfcheckSha256': identity.sha(__file__), 'positiveSchemaChecks': positives,
        'negativeGateChecks': negatives, 'sourceEvidence': evidence})
    print(json.dumps({'positiveSchemaChecks': len(positives), 'negativeGateChecks': len(negatives),
                      'benchmarkJvmsLaunched': 0, 'output': str(args.output)}))


if __name__ == '__main__':
    main()
